with latest as (select *, row_number() over (partition by region order by opened_date desc nulls last, id) as latest_rank from stores qualify latest_rank = 1) select date_trunc('week', opened_date) as week_start, case when sqft >= 12680 then 'LARGE' else 'SMALL' end as sqft_tier, percentile_approx(sqft, array(0.25, 0.5, 0.75)) as sqft_quartiles, bit_and(sqft) as sqft_bit_and, count(distinct city) as distinct_cities, sort_array(collect_set(region)) as region_list, approx_percentile(sqft, array(0.25, 0.5, 0.75)) as sqft_quartiles_2, dense_rank() over (partition by date_trunc('week', opened_date) order by bit_and(sqft) desc) as sqft_bit_and_dense_rank from latest group by date_trunc('week', opened_date), case when sqft >= 12680 then 'LARGE' else 'SMALL' end order by sqft_bit_and nulls last;
